<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&amp;display=swap');

        body {
            font-family: "Times New Roman", serif;
            margin: 0;
            padding: 0;
            background: #fff;
            line-height: 1.4;
            max-width: 100%;
            box-sizing: border-box;
        }

        .container {
            margin: 0 auto;
            padding: 40px 50px;
            box-sizing: border-box;
            max-width: 100%;
        }

        .header {
            text-align: center;
            margin-bottom: 40px;
            border-bottom: 1px solid #000;
            padding-bottom: 10px;
        }

        .header h1 {
            font-size: 16pt;
            font-weight: 700;
            letter-spacing: 2px;
            margin: 0 0 5px 0;
        }

        .header p {
            font-size: 10pt;
            margin: 0;
            font-style: italic;
        }

        .date {
            text-align: right;
            font-size: 10pt;
            margin-bottom: 30px;
        }

        .title {
            text-align: center;
            font-size: 12pt;
            font-weight: bold;
            margin: 20px 0;
            text-decoration: underline;
        }

        p {
            text-align: justify;
            margin: 12px 0;
            text-indent: 0;
        }

        .section {
            margin: 25px 0 10px 0;
            font-size: 11pt;
            font-weight: bold;
        }

        .content {
            margin-left: 30px;
        }

        ul {
            margin: 8px 0 8px 40px;
            padding: 0;
            list-style-type: disc;
        }

        li {
            margin: 5px 0;
        }

        .placeholder {
            width: 100%;
            height: 200px;
            background: #f0f0f0;
            border: 1px dashed #999;
            margin: 20px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12pt;
            color: #666;
            text-align: center;
            box-sizing: border-box;
        }

        .placeholder-caption {
            font-size: 10pt;
            color: #888;
            margin-top: 8px;
        }

        .footer {
            margin-top: 60px;
            border-top: 1px solid #000;
            padding-top: 10px;
            font-size: 9pt;
            text-align: center;
        }

        @media print {
            body { background: #fff; }
            .container { padding: 0; }
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- Header -->
        <div class="header">
            <h1>PROJECT TITLE</h1>
            <p>Subheading or tagline here</p>
        </div>

        <!-- Date -->
        <div class="date">
            [Date]
        </div>

        <!-- Main Title -->
        <div class="title">
            [Main Title]
        </div>

        <!-- Placeholder for image -->
        <div class="placeholder">
            [Image: centered photograph]
            <div class="placeholder-caption">[Image: top-center, width 100%, height approx. 200px]</div>
        </div>

        <!-- Paragraphs -->
        <p>
            [First paragraph of text. This is a sample paragraph demonstrating the body text layout. In the original document it would be indented or aligned according to the page's typography.]
        </p>

        <p>
            [Second paragraph continuing the text. The document may have multiple columns or specific spacing between paragraphs. This section is placed here to match the typical page flow.]
        </p>

        <!-- Section heading -->
        <div class="section">
            SECTION 1
        </div>

        <div class="content">
            <p>
                [Sub-section content. Text may continue in the same column or move to the next.]
            </p>
            <ul>
                <li>Item one from the list</li>
                <li>Item two from the list</li>
                <li>Item three from the list</li>
            </ul>
        </div>

        <!-- Placeholder for diagram -->
        <div class="placeholder" style="margin-top: 30px;">
            [Diagram: left-aligned]
            <div class="placeholder-caption">[Diagram: bottom, width 40%, height 100px]</div>
        </div>

        <!-- Another paragraph -->
        <p>
            [Continuing text after the diagram placeholder. This maintains the flow of the document.]
        </p>

        <!-- Footer -->
        <div class="footer">
            [Footer text: page number, copyright, or contact info]
        </div>
    </div>
</body>
</html>
